#[cfg(any(target_os="linux",target_os="windows"))]mod platform{
use std::{sync::Arc,path::PathBuf};use ingetrazo_gui::{native_vulkan::{App,System,cad2d::arena::Handle},image_outline_chunks::{PlaneOutlineChunk,ChunkFrame}};use ingetrazo_render::cad2d::{Geometry,Vertex,Batch,EncodedRgba,Pose};
struct Fixture{handle:Handle,original:Vec<Option<Arc<PlaneOutlineChunk>>>,phase:String,frames:u64,path:PathBuf,pending:Option<String>}
fn chunks()->Vec<Option<Arc<PlaneOutlineChunk>>>{[(20.,[255,0,0,255]),(300.,[0,0,255,255])].into_iter().map(|(x,color)|Some(Arc::new(PlaneOutlineChunk{geometry:Geometry::new(vec![Vertex{position:[x,20.],coverage:1.},Vertex{position:[x+180.,20.],coverage:1.},Vertex{position:[x+180.,180.],coverage:1.},Vertex{position:[x,180.],coverage:1.}],vec![0,1,2,0,2,3]).unwrap(),batches:vec![Batch{first:0,count:6,color:EncodedRgba::from_bytes(color,1.).unwrap()}].into(),strips:1}))).collect()}
impl App for Fixture{
 fn title()->&'static str{"IngeTrazo outline arena lifetime fixture"}
 fn new(system:&mut System,_:Option<PathBuf>)->Self{let properties=unsafe{system.vulkan_context.instance.get_physical_device_properties(system.vulkan_context.physical_device)};eprintln!("Renderer device: {}",serde_json::json!({"name":unsafe{std::ffi::CStr::from_ptr(properties.device_name.as_ptr())}.to_string_lossy(),"vendor_id":properties.vendor_id,"device_type":format!("{:?}",properties.device_type)}));let renderer=system.enable_cad2d().unwrap();let handle=renderer.factory().outline_arena();system.cad2d.as_mut().unwrap().configure_outline_arena_for_probe(64,None).unwrap();let original=chunks();handle.update(ChunkFrame{slots:&original,changed:&[0,1],replacement:true,serial:1},Pose::default()).unwrap();Self{handle,original,phase:"baseline".into(),frames:0,path:std::env::var("INGETRAZO_ARENA_PROBE_PATH").unwrap().into(),pending:None}}
 fn build_ui(&mut self,ctx:&egui::Context){self.frames+=1;if let Ok(request)=std::fs::read_to_string(self.path.join("advance")){std::fs::remove_file(self.path.join("advance")).unwrap();self.pending=Some(request.trim().into());}egui::CentralPanel::default().frame(egui::Frame::none().fill(egui::Color32::WHITE)).show(ctx,|ui|{ui.painter().add(self.handle.shape(ui.max_rect()));});ctx.request_repaint_after(std::time::Duration::from_millis(25));if ctx.input(|i|i.viewport().close_requested()){ctx.send_viewport_cmd(egui::ViewportCommand::Close);}}
 fn prepare_gpu(&mut self,system:&mut System,resize:bool){if resize{return;}if let Some(request)=self.pending.take(){match request.as_str(){"pressure"=>{system.verify_outline_candidate_rollback_for_probe(&self.handle).unwrap();self.phase="refused".into();self.frames=0;},"retry"=>{let modified=self.original.iter().map(|chunk|{let chunk=chunk.as_ref().unwrap();let mut vertices=chunk.geometry.vertices().to_vec();for v in &mut vertices{v.position[0]+=10.;}Some(Arc::new(PlaneOutlineChunk{geometry:Geometry::new(vertices,chunk.geometry.indices().to_vec()).unwrap(),batches:chunk.batches.clone(),strips:chunk.strips}))}).collect::<Vec<_>>();self.handle.update(ChunkFrame{slots:&modified,changed:&[0,1],replacement:false,serial:4},Pose{translation:[7.,11.],..Default::default()}).unwrap();self.phase="retry".into();self.frames=0;},"one"=>{let modified=self.original.iter().enumerate().map(|(index,chunk)|{let chunk=chunk.as_ref().unwrap();let mut vertices=chunk.geometry.vertices().to_vec();for v in &mut vertices{v.position[0]+=if index==0{11.}else{10.};}Some(Arc::new(PlaneOutlineChunk{geometry:Geometry::new(vertices,chunk.geometry.indices().to_vec()).unwrap(),batches:chunk.batches.clone(),strips:chunk.strips}))}).collect::<Vec<_>>();self.handle.update(ChunkFrame{slots:&modified,changed:&[0],replacement:false,serial:5},Pose{translation:[7.,11.],..Default::default()}).unwrap();self.phase="one".into();self.frames=0;},_=>panic!("Unknown probe request")}}
 let state=serde_json::json!({"phase":self.phase,"frames":self.frames,"stats":system.cad2d.as_ref().unwrap().outline_arena_stats()});let temp=self.path.join("state.tmp");std::fs::write(&temp,serde_json::to_vec_pretty(&state).unwrap()).unwrap();std::fs::rename(temp,self.path.join("state.json")).unwrap();}
 fn gpu_error(&mut self,error:&str){panic!("Arena fixture actual GPU error: {error}");}
}
pub fn main()->Result<(),Box<dyn std::error::Error>>{ingetrazo_gui::native_vulkan::run_app::<Fixture>(None)}
}
#[cfg(any(target_os="linux",target_os="windows"))]fn main()->Result<(),Box<dyn std::error::Error>>{platform::main()}
